import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        nums.add({a});
        nums.add({b});
        nums.add({c});

        System.out.println("加起来是 " + nums.stream().mapToInt(n -> n).sum());
    }
}
